/* Relaywise. Tokens and rationale live in DESIGN.md. */
:root {
  --bg: oklch(0.985 0.004 250);
  --surface: oklch(1 0 0);
  --ink: oklch(0.22 0.02 260);
  --muted: oklch(0.47 0.02 260);
  --line: oklch(0.62 0.02 260);      /* control edges: 3:1+ on surface */
  --hairline: oklch(0.9 0.008 260);  /* decorative separators only */
  --accent: oklch(0.45 0.16 265);    /* stamp ink: primary action + stamp */
  --accent-press: oklch(0.38 0.16 265);
  --chip: oklch(0.94 0.02 265);
  --slip: oklch(0.93 0.05 85);       /* manila routing slip */
  --slip-ink: oklch(0.4 0.05 70);
  --slip-rule: oklch(0.8 0.05 80);
  --foot-muted: oklch(0.8 0.015 260);
  --foot-ring: oklch(0.8 0.1 265);

  --font: "Archivo", system-ui, -apple-system, "Segoe UI", sans-serif;
  --r-sm: 0.25rem;
  --r-md: 0.5rem;
  --r-lg: 0.875rem;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
  --header-h: 4rem;
}

*, *::before, *::after { box-sizing: border-box; }

html {
  scroll-padding-top: calc(var(--header-h) + 1rem);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font);
  font-size: 1.0625rem;
  line-height: 1.6;
  caret-color: var(--accent);
}

::selection { background: var(--slip); color: var(--ink); }

h1, h2, h3 { margin: 0; text-wrap: balance; }
p { margin: 0; text-wrap: pretty; }
ul, ol { margin: 0; padding: 0; list-style: none; }

a { color: var(--accent); text-underline-offset: 0.2em; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: var(--r-sm);
}

.vh {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

.skip {
  position: absolute; left: 1rem; top: -4rem; z-index: 30;
  padding: 0.75rem 1rem; background: var(--ink); color: var(--surface);
  border-radius: var(--r-md);
}
.skip:focus { top: 1rem; }

.wrap {
  width: min(100% - 2.5rem, 72rem);
  margin-inline: auto;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  min-height: 2.875rem; padding: 0.75rem 1.375rem;
  border-radius: var(--r-md);
  font: inherit; font-weight: 650; line-height: 1.2; text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease), border-color 180ms var(--ease), transform 80ms var(--ease);
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: var(--surface); }
.btn-primary:active { background: var(--accent-press); }
.btn-secondary { background: var(--surface); color: var(--ink); border: 1.5px solid var(--line); }
.btn-secondary:active { border-color: var(--ink); }
.btn-small { min-height: 2.5rem; padding: 0.5rem 1rem; font-size: 0.9375rem; }

@media (hover: hover) {
  .btn-primary:hover { background: var(--accent-press); }
  .btn-secondary:hover { border-color: var(--ink); }
  .nav a:hover, .more:hover, .site-footer a:hover { text-decoration-thickness: 2px; }
}

/* ---------- Header ---------- */
.site-header {
  position: sticky; top: 0; z-index: 20;
  background: var(--bg);
  border-bottom: 1px solid var(--hairline);
}
.header-row {
  display: flex; align-items: center; gap: 1.5rem;
  min-height: var(--header-h);
}
.wordmark {
  color: var(--ink); text-decoration: none;
  font-weight: 800; font-stretch: 118%; font-size: 1.25rem; letter-spacing: -0.01em;
}
.site-header nav { margin-left: auto; }
.nav { display: flex; gap: 1.5rem; }
.nav a {
  display: inline-block; padding-block: 0.5rem;
  color: var(--ink); text-decoration: none; font-weight: 500;
}
.nav a:active { text-decoration: underline; }

@media (max-width: 40rem) {
  .nav li:not(:last-child) { display: none; } /* ponytail: small screens keep Sign in + trial; sections are one scroll away */
  .header-row { gap: 1rem; }
}

/* ---------- Hero ---------- */
.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr);
  gap: clamp(2.5rem, 6vw, 5rem);
  align-items: center;
  padding-block: clamp(3.5rem, 9vw, 7rem) clamp(4rem, 9vw, 7.5rem);
}
.hero h1 {
  font-size: clamp(2.375rem, 1.4rem + 3.6vw, 4.25rem);
  font-weight: 800; font-stretch: 112%;
  line-height: 1.04; letter-spacing: -0.03em;
}
.lede {
  margin-top: 1.5rem; max-width: 36rem;
  font-size: 1.1875rem; color: var(--muted);
}
.hero-actions {
  display: flex; flex-wrap: wrap; align-items: center; gap: 0.75rem 1.25rem;
  margin-top: 2.25rem;
}
.fine { color: var(--muted); font-size: 0.9375rem; }

/* The demo: an email with its routing slip clipped on */
.demo { position: relative; margin: 0; padding-bottom: 5.5rem; }
.email {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
  padding: 1.5rem 1.5rem 3.5rem;
  box-shadow: 0 1px 2px oklch(0.22 0.02 260 / 0.06), 0 12px 32px -12px oklch(0.22 0.02 260 / 0.18);
}
.label {
  display: inline-block; min-width: 2.75rem;
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase;
  color: var(--muted);
}
.email-meta { font-size: 0.9375rem; }
.email-subject { margin-top: 0.75rem; font-weight: 700; font-size: 1.25rem; line-height: 1.3; }
.email-body { margin-top: 0.5rem; color: var(--muted); }

.slip {
  position: absolute; right: -0.75rem; bottom: 0;
  width: min(19rem, 88%);
  background:
    repeating-linear-gradient(to bottom, transparent 0 2.4rem, var(--slip-rule) 2.4rem calc(2.4rem + 1px)) 0 2.6rem / 100% calc(100% - 2.6rem) no-repeat,
    var(--slip);
  color: var(--slip-ink);
  border-radius: var(--r-sm);
  padding: 0.875rem 1.25rem 1rem;
  transform: rotate(2deg);
  box-shadow: 0 10px 24px -14px oklch(0.3 0.05 70 / 0.45);
}
.slip-title {
  font-weight: 800; font-stretch: 75%; font-size: 0.875rem;
  letter-spacing: 0.08em; text-transform: uppercase;
  padding-bottom: 0.5rem;
}
.slip-lines li { display: flex; align-items: center; min-height: 2.4rem; }
.slip-lines .label { color: var(--slip-ink); }
.slip-lines del { text-decoration-thickness: 2px; }
.slip-final { color: var(--ink); }

/* The stamp: the one signature device. Real text, never an image. */
.stamp {
  display: inline-block;
  padding: 0.125rem 0.625rem;
  border: 2.5px solid currentColor;
  border-radius: var(--r-sm);
  color: var(--accent);
  font-weight: 800; font-stretch: 70%; font-size: 1.375rem;
  letter-spacing: 0.06em; text-transform: uppercase; line-height: 1.25;
  transform: rotate(-4deg);
  box-shadow: inset 0 0 0 2px var(--slip), inset 0 0 0 3.5px currentColor;
}
.slip .stamp { animation: stamp-in 420ms var(--ease) 500ms backwards; }

@keyframes stamp-in {
  from { transform: rotate(-4deg) scale(1.35); opacity: 0; }
  60%  { opacity: 1; }
  to   { transform: rotate(-4deg) scale(1); opacity: 1; }
}

.demo-caption {
  position: absolute; left: 0; bottom: 0;
  width: calc(100% - min(19rem, 88%) - 1.5rem);
  font-size: 0.875rem; color: var(--muted); line-height: 1.45;
}

/* ---------- Section heads ---------- */
.section-head { max-width: 40rem; }
.section-head h2 {
  font-size: clamp(1.875rem, 1.3rem + 2vw, 2.75rem);
  font-weight: 800; font-stretch: 112%;
  line-height: 1.1; letter-spacing: -0.025em;
}
.section-head p { margin-top: 1rem; color: var(--muted); font-size: 1.125rem; }

/* ---------- Features ---------- */
.features {
  background: var(--surface);
  border-block: 1px solid var(--hairline);
  padding-block: clamp(4rem, 8vw, 6.5rem);
}
.features .section-head {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 1rem 3rem; align-items: end; max-width: none;
}
.features .section-head p { margin-top: 0; max-width: 34rem; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: 1rem;
  margin-top: 3rem;
}
.card {
  display: flex; flex-direction: column;
  padding: 1.5rem;
  background: var(--bg);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  min-width: 0;
}
.card h3 { font-size: 1.1875rem; font-weight: 750; line-height: 1.3; }
.card p { margin-top: 0.5rem; color: var(--muted); }
.chips { display: flex; flex-wrap: wrap; gap: 0.375rem; margin-top: 1.25rem; }
.chip {
  padding: 0.125rem 0.625rem;
  background: var(--chip); color: var(--ink);
  border-radius: 999px;
  font-size: 0.8125rem; font-weight: 600; line-height: 1.6;
}
.chip-beta { background: var(--slip); color: var(--slip-ink); }
.more {
  align-self: flex-start;
  margin-top: auto; padding-top: 1.25rem; padding-block-end: 0.125rem;
  font-weight: 650;
}
.more:active { color: var(--accent-press); }

/* ---------- Pricing ---------- */
.pricing { padding-block: clamp(4.5rem, 9vw, 7rem); }
.tiers {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.25rem;
  margin-top: 3rem;
  align-items: stretch;
}
.tier {
  position: relative;
  display: flex; flex-direction: column;
  padding: 1.75rem;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: var(--r-lg);
}
.tier-pick {
  border: 2px solid var(--accent);
  box-shadow: 0 16px 40px -20px oklch(0.45 0.16 265 / 0.45);
}
.tier h3 { font-size: 1.375rem; font-weight: 800; font-stretch: 112%; }
.stamp-tier {
  position: absolute; top: -1rem; right: 1.25rem;
  font-size: 0.9375rem;
  background: var(--surface);
  box-shadow: inset 0 0 0 2px var(--surface), inset 0 0 0 3.5px currentColor;
}
.tier-for { margin-top: 0.375rem; color: var(--muted); font-size: 0.9375rem; }
.price { margin-top: 1.5rem; display: flex; align-items: baseline; gap: 0.375rem; }
.amount {
  font-size: 2.75rem; font-weight: 800; font-stretch: 105%;
  line-height: 1; letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}
.per { color: var(--muted); }
.tier-features {
  margin-top: 1.5rem; padding-top: 1.25rem;
  border-top: 1px solid var(--hairline);
  display: grid; gap: 0.625rem;
  margin-bottom: 2rem;
}
.tier-features li { position: relative; padding-left: 1.5rem; }
.tier-features li::before {
  content: ""; position: absolute; left: 0.125rem; top: 0.45em;
  width: 0.5rem; height: 0.8rem;
  border: solid var(--accent); border-width: 0 2.5px 2.5px 0;
  transform: rotate(40deg);
}
.tier .btn { margin-top: auto; }

/* ---------- Footer ---------- */
.site-footer {
  background: var(--ink); color: var(--surface);
  padding-block: 4rem 2rem;
  line-height: 1.5;
}
.site-footer :focus-visible { outline-color: var(--foot-ring); }
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, minmax(0, 1fr));
  gap: 2.5rem 2rem;
}
.site-footer .wordmark { color: var(--surface); }
.footer-brand p { margin-top: 0.5rem; color: var(--foot-muted); }
.footer-col h2 {
  font-size: 0.875rem; font-weight: 700; letter-spacing: 0.02em;
  color: var(--surface);
}
.footer-col ul { margin-top: 0.75rem; display: grid; gap: 0.25rem; }
.footer-col a {
  display: inline-block; padding-block: 0.25rem;
  color: var(--foot-muted); text-decoration: none;
}
.footer-col a:active { color: var(--surface); }
@media (hover: hover) { .footer-col a:hover { color: var(--surface); text-decoration: underline; } }
.footer-base {
  margin-top: 3rem; padding-top: 1.5rem;
  border-top: 1px solid oklch(0.4 0.02 260);
  color: var(--foot-muted); font-size: 0.875rem;
}

/* ---------- Responsive ---------- */
@media (max-width: 60rem) {
  .hero { grid-template-columns: minmax(0, 1fr); }
  .demo { max-width: 32rem; }
  .tiers { grid-template-columns: minmax(0, 1fr); max-width: 30rem; }
  .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 45rem) {
  .features .section-head { grid-template-columns: minmax(0, 1fr); }
  .demo { padding-bottom: 0; }
  .slip { position: relative; right: auto; margin: -2.5rem 0 0 auto; }
  .demo-caption { position: static; width: auto; margin-top: 1.25rem; }
}

@media (pointer: coarse) {
  .nav a, .footer-col a { padding-block: 0.625rem; }
}

/* Reduced motion: the stamp just sits there, fully visible. Colour changes stay. */
@media (prefers-reduced-motion: reduce) {
  .slip .stamp { animation: none; }
  .btn:active { transform: none; }
}

