  gap: 2.5rem 2rem;
}
.site-footer .wordmark { color: var(--surface); }
.footer-brand p { margin-top: 0.5rem; color: var(--foot-muted); }
.footer-col h2 {
  font-size: 0.875rem; font-weight: 700; letter-spacing: 0.02em;
  color: var(--surface);
}
.footer-col ul { margin-top: 0.75rem; display: grid; gap: 0.25rem; }
.footer-col a {
  display: inline-block; padding-block: 0.25rem;
  color: var(--foot-muted); text-decoration: none;
}
.footer-col a:active { color: var(--surface); }
@media (hover: hover) { .footer-col a:hover { color: var(--surface); text-decoration: underline; } }
.footer-base {
  margin-top: 3rem; padding-top: 1.5rem;
  border-top: 1px solid oklch(0.4 0.02 260);
  color: var(--foot-muted); font-size: 0.875rem;
}

/* ---------- Responsive ---------- */
@media (max-width: 60rem) {
  .hero { grid-template-columns: minmax(0, 1fr); }
  .demo { max-width: 32rem; }
  .tiers { grid-template-columns: minmax(0, 1fr); max-width: 30rem; }
  .footer-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 45rem) {
  .features .section-head { grid-template-columns: minmax(0, 1fr); }
  .demo { padding-bottom: 0; }
  .slip { position: relative; right: auto; margin: -2.5rem 0 0 auto; }
  .demo-caption { position: static; width: auto; margin-top: 1.25rem; }
}

@media (pointer: coarse) {
  .nav a, .footer-col a { padding-block: 0.625rem; }
}

/* Reduced motion: the stamp just sits there, fully visible. Colour changes stay. */
@media (prefers-reduced-motion: reduce) {
  .slip .stamp { animation: none; }
  .btn:active { transform: none; }
}

